    best_node = unvisited_nodes[0]
    for candidate in unvisited_nodes:
        dist_current = distance_matrix[current_node, candidate]
        # count other unvisited nodes that have candidate as their closest unvisited node
        count = 0
        others = unvisited_nodes[unvisited_nodes != candidate]
        for u in others:
            # find the minimum distance from u to any other unvisited node (excluding u and candidate)
            min_dist_to_other = np.inf
            for v in unvisited_nodes:
                if v == u or v == candidate:
                    continue
                d = distance_matrix[u, v]
                if d < min_dist_to_other:
                    min_dist_to_other = d
