                count += 1
        score = dist_current * count
        if score > best_score:
            best_score = score
            best_node = candidate
    return best_node

def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    best_score = np.inf
    best_node = unvisited_nodes[0]
    for u in unvisited_nodes:
        d_curr = distance_matrix[current_node, u]
        d_dest = distance_matrix[u, destination_node]
        others = unvisited_nodes[unvisited_nodes != u]
        if len(others) > 0:
            avg_others = np.mean(distance_matrix[u, others])
        else:
            avg_others = 1.0  # to avoid division by zero
        score = d_curr + d_dest / (avg_others + 1e-12)
        if score < best_score:
            best_score = score
            best_node = u
    return best_node

import numpy as np

def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    n_unvisited = len(unvisited_nodes)
    if n_unvisited == 0:
        return destination_node
    if n_unvisited == 1:
        return unvisited_nodes[0]

    best_score = np.inf
    best_node = unvisited_nodes[0]

    for candidate in unvisited_nodes:
        dist_current = distance_matrix[current_node, candidate]
        others = unvisited_nodes[unvisited_nodes != candidate]
        dists_to_others = distance_matrix[candidate, others]

        if np.any(dists_to_others == 0):
            geo_mean = 0.0
        else:
            geo_mean = np.exp(np.mean(np.log(dists_to_others)))

        score = dist_current * geo_mean
        if score < best_score:
            best_score = score
            best_node = candidate

    return best_node

def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    n_unvisited = len(unvisited_nodes)
    if n_unvisited == 0:
        return destination_node
    if n_unvisited == 1:
        return unvisited_nodes[0]

    best_score = np.inf
    best_node = unvisited_nodes[0]
    for candidate in unvisited_nodes:
        dist_current = distance_matrix[current_node, candidate]
        others = unvisited_nodes[unvisited_nodes != candidate]
        if len(others) > 0:
            dists_to_others = distance_matrix[candidate, others]
            median_dist = np.median(dists_to_others)
        else:
            median_dist = 0
        factor = 1.0 / n_unvisited
        score = dist_current + median_dist * factor
        if score < best_score:
            best_score = score
            best_node = candidate
    return best_node
